const request = require('request');

const options = {
  method: 'GET',
  url: 'https://api.procore.com/rest/v1.0/projects/%7Bproject_id%7D/people',
  qs: {
    view: 'SOME_STRING_VALUE',
    page: 'SOME_INTEGER_VALUE',
    per_page: 'SOME_INTEGER_VALUE',
    'filters[is_employee]': 'SOME_BOOLEAN_VALUE',
    'filters[reference_users_only]': 'SOME_BOOLEAN_VALUE',
    'filters[without_reference_users]': 'SOME_BOOLEAN_VALUE',
    'filters[include_company_people]': 'SOME_BOOLEAN_VALUE',
    'filters[search]': 'SOME_STRING_VALUE',
    'filters[connected]': 'SOME_BOOLEAN_VALUE',
    'filters[vendor_id]': 'SOME_ARRAY_VALUE',
    'filters[job_title]': 'SOME_STRING_VALUE',
    'filters[country_code]': 'SOME_STRING_VALUE',
    'filters[state_code]': 'SOME_STRING_VALUE',
    'filters[trade_id]': 'SOME_ARRAY_VALUE',
    'filters[permission_template_id]': 'SOME_ARRAY_VALUE',
    sort: 'SOME_STRING_VALUE'
  }
};

request(options, function (error, response, body) {
  if (error) throw new Error(error);

  console.log(body);
});

var client = new HttpClient();
var request = new HttpRequestMessage
{
    Method = HttpMethod.Get,
    RequestUri = new Uri("https://api.procore.com/rest/v1.0/projects/%7Bproject_id%7D/people?view=SOME_STRING_VALUE&page=SOME_INTEGER_VALUE&per_page=SOME_INTEGER_VALUE&filters%5Bis_employee%5D=SOME_BOOLEAN_VALUE&filters%5Breference_users_only%5D=SOME_BOOLEAN_VALUE&filters%5Bwithout_reference_users%5D=SOME_BOOLEAN_VALUE&filters%5Binclude_company_people%5D=SOME_BOOLEAN_VALUE&filters%5Bsearch%5D=SOME_STRING_VALUE&filters%5Bconnected%5D=SOME_BOOLEAN_VALUE&filters%5Bvendor_id%5D=SOME_ARRAY_VALUE&filters%5Bjob_title%5D=SOME_STRING_VALUE&filters%5Bcountry_code%5D=SOME_STRING_VALUE&filters%5Bstate_code%5D=SOME_STRING_VALUE&filters%5Btrade_id%5D=SOME_ARRAY_VALUE&filters%5Bpermission_template_id%5D=SOME_ARRAY_VALUE&sort=SOME_STRING_VALUE"),
};
using (var response = await client.SendAsync(request))
{
    response.EnsureSuccessStatusCode();
    var body = await response.Content.ReadAsStringAsync();
    Console.WriteLine(body);
}

